func TestConcurrentAllow(t *testing.T) {
	clk := newFakeClock(time.Unix(0, 0))
	l, err := New(100, 0.0001, clk) // effectively no refill during test
	if err != nil {
		t.Fatalf("New() error = %v", err)
	}
	const goroutines = 50
	var wg sync.WaitGroup
	var allowed int64
	var mu sync.Mutex
	for i := 0; i < goroutines; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for j := 0; j < 10; j++ {
				if l.AllowN(clk.Now(), 1) {
					mu.Lock()
					allowed++
					mu.Unlock()
				}
			}
		}()
	}
	wg.Wait()
	if allowed != 100 {
		t.Errorf("allowed = %d, want exactly 100 (capacity)", allowed)
	}
}
